function chipFor(verdict){
  if (verdict === "HOLD") return {cls:"hold", label:"HOLD · conflict predicted"};
  if (verdict === "CAUTION") return {cls:"adv", label:"CAUTION · advisories"};
  if (verdict === "CLEARED_PARTIAL")
    return {cls:"adv", label:"CLEARED · partial analysis"};
  if (verdict === "CLEARED") return {cls:"clear", label:"CLEARED"};
  return {cls:"adv", label:verdict || "UNKNOWN"};
}
function pairOf(fl){
  if (conflictBranches.has(fl.branch)) return red;
  if (fl.branch === prior.a) return prior;
  return clean;
}
function statusOf(fl){
  const chip = chipFor(pairOf(fl).result.verdict);
  if (fl.branch === prior.a && priors.length && chip.cls === "clear")
    return {cls:"adv", label:chip.label + " · turbulence advisory"};
  return chip;
}
function gapsOf(fl){
  const an = pairOf(fl).result.analysis;
  return (an && an.gaps) ? an.gaps.length : 0;
}

